      const char *wpo_mono = link_abi_getenv("XLANG_WPO_MONO");
      const char *wpo_nofold = link_abi_getenv("XLANG_WPO_NO_FOLD");
      if ((wpo_mono && wpo_mono[0]) || (wpo_nofold && wpo_nofold[0]))
        cfold_use_imm32 = 0;
