static inline int32_t win_return_load_i32(const void *p, int32_t off) {
  const uint8_t *b = (const uint8_t *)p + off;
  return (int32_t)((uint32_t)b[0] | ((uint32_t)b[1] << 8) | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24));
}

/**
 * Windows leftover-PE hybrid return_impl (wave144 cold face).
 * TYPE_ARRAY `return a` of a local [N]T: SAT remaining-wave Path B0 is
 * `#ifndef FROM_X` ABSENT; emit_expr of VAR load_var payload then the
 * caller treats rax as E* (`arr_ret_whole` SEGV 139). G.7 complete
 * leftover rest unique emit_return (already first-wins T): POSIX Path B0
 * durable COMMON via leftover rest unique helper. ARRAY_LIT stays
 * mega_body durable. Do not leftover rest remaining-wave emit_return
 * via !FROM_X || WIN.
 * PLATFORM: WINDOWS leftover-PE hybrid; POSIX FROM_X path remains unchanged.
 */
int32_t pipeline_asm_emit_return_elf_impl(void *arena, void *elf_ctx, int32_t expr_ref,
                                          void *ctx, int32_t ta) {
  uint8_t *ly;
  int32_t ret_op;
  int32_t tj_len;
  int32_t ti;
  uint8_t tj_lbl[128];
  int32_t ret_rty;
  int32_t ret_rtk;
  int32_t ret_fi;
  void *ret_mod;
  int32_t ret_st;

  ly = (uint8_t *)pipeline_asm_ctx_layout(ctx);
  ret_op = pipeline_expr_unary_operand_ref_at(arena, expr_ref);
  if (ret_op != 0) {
    ret_st = -2;
    ret_rty = 0;
    ret_rtk = 0;
    ret_mod = pipeline_asm_emit_module_ref_c();
    ret_fi = pipeline_asm_emit_func_index_c();
    if (ret_mod && ret_fi >= 0)
      ret_rty = pipeline_module_func_return_type_at(ret_mod, ret_fi);
    if (ret_rty <= 0)
      ret_rty = pipeline_expr_resolved_type_ref(arena, ret_op);
    if (ret_rty > 0)
      ret_rtk = pipeline_type_kind_ord_at(arena, ret_rty);
    if (ret_rty > 0 && ret_rtk == 10)
      ret_st = glue_emit_fixed_array_return_durable_ptr_rax_elf_c(arena, elf_ctx, ret_op, ctx, ta,
                                                                 ret_rty);
    if (ret_st == -1)
      return -1;
    if (ret_st != 0) {
      if (pipeline_asm_emit_expr_elf_c(arena, elf_ctx, ret_op, ctx, ta) != 0)
        return -1;
    }
  }
  if (glue_index_scratch_spills_cleanup_all_elf_c(elf_ctx, ta) != 0)
    return -1;
  if (glue_async_cps_emit_phase_reset(elf_ctx, ta) != 0)
    return -1;
  if (!ly)
    return -1;
  tj_len = win_return_load_i32(ly, 1520 /* W144_LY_TAIL_JOIN_LEN */);
  if (tj_len <= 0)
    return -1;
  for (ti = 0; ti < tj_len && ti < 128; ti++)
    tj_lbl[ti] = ly[1392 /* W144_LY_TAIL_JOIN_LBL */ + ti];
  return backend_enc_jmp_arch(elf_ctx, tj_lbl, tj_len, ta);
}

/**
 * Windows leftover-PE: get_return expr_stmts fallback must return RETURN operand.
 * Seed #ifndef FROM_X twin is excluded from FROM_X rest; standalone/.x amalgam
 * still has historical `return 0` on EXPR_RETURN which yields empty .text when
 * stmt_order is 0. Rest links before thin → same-TU mega binds here.
 * Reads W277_Block fields via arena pointer (avoid ast_ast_block_* PE stubs).
 * PLATFORM: WINDOWS leftover-PE hybrid.
 */
extern int32_t pipeline_block_num_labeled_stmts(void *a, int32_t body_ref);
extern int32_t pipeline_block_labeled_return_expr_ref(void *a, int32_t body_ref, int32_t j);
extern int32_t pipeline_block_expr_stmt_ref(void *a, int32_t body_ref, int32_t ei);
extern int32_t pipeline_expr_kind_ord_at(void *a, int32_t expr_ref);
extern int32_t pipeline_expr_unary_operand_ref_at(void *a, int32_t expr_ref);
extern void *pipeline_arena_block_ptr(void *a, int32_t br);
extern int32_t pipeline_asm_module_func_body_ref_at(void *m, int32_t func_index);

static int32_t win_blk_i32(const void *b, int32_t off) {
  const uint8_t *p = (const uint8_t *)b + off;
  return (int32_t)((uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) |
                   ((uint32_t)p[3] << 24));
}

int32_t pipeline_backend_get_return_expr_ref(void *a, void *f) {
  int32_t body_ref;
  int32_t nblocks;
  int32_t nexprs;
  int32_t j;
  int32_t nlab;
  int32_t ret_ref;
  int32_t fin;
  int32_t ei;
  int32_t nstmt;
  int32_t ers;
  int32_t ko;
  int32_t op;
  uint8_t *ab;
  uint8_t *fb;
  void *blk;
  if (!a || !f)
    return 0;
  ab = (uint8_t *)a;
  fb = (uint8_t *)f;
  /* Func.body_ref @148; Arena.num_exprs @4; Arena.num_blocks @8 (W144/W277). */
  body_ref = win_blk_i32(fb, 148);
  nexprs = win_blk_i32(ab, 4);
  nblocks = win_blk_i32(ab, 8);
  if (body_ref <= 0 || body_ref > nblocks)
    return 0;
  blk = pipeline_arena_block_ptr(a, body_ref);
  if (!blk)
    return 0;
  nlab = pipeline_block_num_labeled_stmts(a, body_ref);
  for (j = 0; j < nlab; j++) {
    ret_ref = pipeline_block_labeled_return_expr_ref(a, body_ref, j);
    if (ret_ref != 0)
      return ret_ref;
  }
  fin = win_blk_i32(blk, 0x4c); /* final_expr_ref */
  if (fin != 0) {
    if (fin <= 0 || fin > nexprs)
      return fin;
    ko = pipeline_expr_kind_ord_at(a, fin);
    op = pipeline_expr_unary_operand_ref_at(a, fin);
    /* Bare `return;` (EXPR_RETURN, op=0): do not hand RETURN node to emit_expr
     * (PE emits a broken self-jmp). Return 0 so mega void-main mov-imm-0 runs.
     * PLATFORM: WINDOWS leftover-PE hybrid. */
    if (ko == 41) {
      if (op != 0)
        return op;
      return 0;
    }
    return fin;
  }
  nstmt = win_blk_i32(blk, 0x48); /* num_expr_stmts */
  for (ei = nstmt - 1; ei >= 0; ei--) {
    ers = pipeline_block_expr_stmt_ref(a, body_ref, ei);
    if (ers != 0 && ers > 0 && ers <= nexprs) {
      ko = pipeline_expr_kind_ord_at(a, ers);
      if (ko == 41) {
        op = pipeline_expr_unary_operand_ref_at(a, ers);
        if (op != 0)
          return op;
        /* Bare return in expr_stmts — same as final_expr bare. */
        return 0;
      }
    }
  }
  return 0;
}

int32_t pipeline_backend_get_return_expr_ref_at(void *a, void *m, int32_t func_index) {
  uint8_t fake_func[160];
  int32_t body_ref;
  int32_t bi;
  if (!a || !m || func_index < 0)
    return 0;
  body_ref = pipeline_asm_module_func_body_ref_at(m, func_index);
  if (body_ref <= 0)
    return 0;
  /* Only body_ref@148 is read by get_return_expr_ref; avoid W280_Func* clash. */
  for (bi = 0; bi < 160; bi++)
    fake_func[bi] = 0;
  fake_func[148] = (uint8_t)(body_ref & 0xff);
  fake_func[149] = (uint8_t)((body_ref >> 8) & 0xff);
  fake_func[150] = (uint8_t)((body_ref >> 16) & 0xff);
  fake_func[151] = (uint8_t)((body_ref >> 24) & 0xff);
  return pipeline_backend_get_return_expr_ref(a, fake_func);
}

int32_t pipeline_asm_get_return_expr_ref_at(void *a, void *m, int32_t func_index) {
  return pipeline_backend_get_return_expr_ref_at(a, m, func_index);
}

/**
 * Windows leftover-PE: stmt_order count via block pointer (avoid multi-def twin).
 * Thin mega cannot be edited; when body has no if/let/loop/for/region and no
 * non-RETURN expr-stmt, report nso=0 so mega takes get_return (redirected)
 * instead of archaeology emit_block. leftover rest emit_block skips RETURN
 * (ko==41) and leftover rest final_expr also skips when stmt_order already
 * has a RETURN — they cancel, so return-only bodies must stay on get_return
 * (`return 42` nexpr may still be 1: leftover-PE parser does not always fold
 * trailing return to final_expr). ASSIGN/CALL without a let
 * (`take(x) { x = 9; return x; }`) is nlet=0 plus a non-RETURN expr-stmt so
 * emit_block still runs. Control / local / unsafe-region keep the real count
 * (`take(p: *i32) { unsafe { return *p; } }` is nlet=0 nreg=1).
 *
 * Also run sparse-if rebuild here: leftover-PE product -c path may skip
 * prepare_entry fixup, leaving ifs in Block.num_if_stmts but absent from
 * stmt_order (emit then only sees fallthrough return → RUN=9 for ifelse).
 * Offsets (W277_Block): num_lets@0x0c, num_loops@0x18, num_for_loops@0x20,
 * num_if_stmts@0x28, num_regions@0x30, num_expr_stmts@0x48,
 * num_stmt_order@0x54.
 * PLATFORM: WINDOWS leftover-PE hybrid.
 */
void pipeline_block_stmt_order_rebuild_sparse_ifs(void *a, int32_t br);

int32_t pipeline_asm_block_num_stmt_order_at(void *a, int32_t br) {
  void *b;
  int32_t nso;
  int32_t nif;
  int32_t nlet;
  int32_t nloop;
  int32_t nfor;
  int32_t nreg;
  int32_t nexpr;
  int32_t ei;
  int32_t er;
  int32_t ko;
  if (!a || br <= 0)
    return 0;
  /* Rebuild before reading counts — idempotent when ifs already in order. */
  pipeline_block_stmt_order_rebuild_sparse_ifs(a, br);
  b = pipeline_arena_block_ptr(a, br);
  if (!b)
    return 0;
  nso = win_blk_i32(b, 0x54);
  nif = win_blk_i32(b, 0x28);
  nlet = win_blk_i32(b, 0x0c);
  nloop = win_blk_i32(b, 0x18);
  nfor = win_blk_i32(b, 0x20);
  nreg = win_blk_i32(b, 0x30);
  nexpr = win_blk_i32(b, 0x48);
  if (nif == 0 && nlet == 0 && nloop == 0 && nfor == 0 && nreg == 0) {
    /* RETURN-only expr-stmts stay on get_return (emit_block+final_expr cancel). */
    if (nexpr <= 0)
      return 0;
    for (ei = 0; ei < nexpr; ei++) {
      er = pipeline_block_expr_stmt_ref(a, br, ei);
      if (er <= 0)
        continue;
      ko = pipeline_expr_kind_ord_at(a, er);
      if (ko != 41)
        return nso;
    }
    return 0;
  }
  return nso;
}

/**
 * Windows leftover-PE: block final_expr emit.
 * EXPR_RETURN must go through leftover rest return_impl (operand + jmp tail).
 * Unwrapping to emit_expr left control in the if-join: then `return 2` became
 * `mov $2; jmp done` with rel32=0, then outer `return 9` overwrote eax
 * (ifelse RUN=9). Thin emit_expr of the RETURN node is CG002.
 * Bare `return;` (op=0) still tail-jmps via return_impl (void-main nso=0 stays
 * on mega get_return and does not call this face).
 * Keep this face freestanding: only call helpers already resolved in the hybrid.
 * PLATFORM: WINDOWS leftover-PE hybrid.
 */
extern int32_t pipeline_asm_emit_expr_elf_rec(void *arena, void *elf_ctx, int32_t expr_ref, void *ctx,
                                               int32_t ta);
extern uint8_t pipeline_block_stmt_order_kind(void *a, int32_t br, int32_t si);
extern int32_t pipeline_block_stmt_order_idx(void *a, int32_t br, int32_t si);
extern int32_t pipeline_asm_emit_return_elf_impl(void *arena, void *elf_ctx, int32_t expr_ref, void *ctx,
                                                 int32_t ta);

int32_t glue_emit_block_final_expr_elf(void *arena, void *elf_ctx, int32_t block_ref, void *ctx, int32_t ta) {
  void *blk;
  int32_t fref;
  int32_t ko;
  int32_t nso;
  int32_t si;
  int32_t idx;
  int32_t er;
  if (!arena || !elf_ctx || !ctx || block_ref <= 0)
    return 0;
  blk = pipeline_arena_block_ptr(arena, block_ref);
  if (!blk)
    return 0;
  fref = win_blk_i32(blk, 0x4c); /* final_expr_ref */
  if (fref == 0)
    return 0;
  /* Skip only when stmt_order already emitted a RETURN expr-stmt (ko==41).
   * kind==2 is any expr_stmt: `x = 4` is also kind 2, and treating it as a
   * return left eax at the let-init (`asgimm` RUN=3). WAVE277 leftover rest
   * expr_stmt_ref is the sidecar authority (G.7 complete).
   * PLATFORM: WINDOWS leftover-PE hybrid. */
  nso = win_blk_i32(blk, 0x54);
  for (si = 0; si < nso; si++) {
    if (pipeline_block_stmt_order_kind(arena, block_ref, si) != 2)
      continue;
    idx = pipeline_block_stmt_order_idx(arena, block_ref, si);
    er = pipeline_block_expr_stmt_ref(arena, block_ref, idx);
    if (er > 0 && pipeline_expr_kind_ord_at(arena, er) == 41)
      return 0;
  }
  ko = pipeline_expr_kind_ord_at(arena, fref);
  if (ko == 41)
    return pipeline_asm_emit_return_elf_impl(arena, elf_ctx, fref, ctx, ta);
  if (pipeline_asm_emit_expr_elf_rec(arena, elf_ctx, fref, ctx, ta) != 0)
    return -1;
  return 0;
}

