    return -1;
  idx = block_pool_append_pos(a, br, &sc->expr_stmt_refs, offsetof(W277_Block, expr_stmt_base), b->num_expr_stmts);
  if (idx < 0)
    return -1;
  pr = (int32_t *)grow_vec_at(&sc->expr_stmt_refs, idx);
  *pr = expr_ref;
  b->num_expr_stmts++;
